    ra_narrow(guest + 8, host + 16, 4, 4, 0, "the host's SDL_Palette.version does not fit in 4 bytes");
    ra_narrow(guest + 12, host + 20, 4, 4, 0, "the host's SDL_Palette.refcount does not fit in 4 bytes");
    memcpy(guest + 16, guest, 16);
