    if (!host) return 0;
    uint64_t guest = ra_object_guest(&ra_objects_SDL_Palette, host);
    if (!guest) guest = ra_object_add(&ra_objects_SDL_Palette, host, 32);
    ra_copy_SDL_Palette((uint8_t *)(uintptr_t)guest, (const uint8_t *)(uintptr_t)host);
    return guest;
